package com.bank.enrich;

// A TINY event: only a few bytes of real payload.
// This is the worst case for header overhead — exactly where compact headers win.
class SwipeEvent {
    private final int cardHash;   // 4 bytes
    private final int amountPaise;// 4 bytes (store money as integer paise here)

    SwipeEvent(int cardHash, int amountPaise) {
        this.cardHash = cardHash;
        this.amountPaise = amountPaise;
    }

    // real business data per object, excluding the JVM header
    static int payloadBytes() { return 8; }

    int getAmountPaise() { return amountPaise; }
}
