package com.bank.enrich;

// Reports the per-object header size for traditional vs compact modes.
class HeaderModel {
    // Traditional header: 8-byte mark word + 4-byte compressed klass = 12,
    // but padding often rounds objects; we use the common 16-byte figure
    // for an object once aligned. Compact header targets 8 bytes.
    static final int TRADITIONAL_HEADER = 12;
    static final int COMPACT_HEADER = 8;

    int headerBytes(boolean compact) {
        return compact ? COMPACT_HEADER : TRADITIONAL_HEADER;
    }

    String describe(boolean compact) {
        return compact
                ? "Compact Object Headers ON  (header = 8 bytes, JEP 519 / Java 25)"
                : "Traditional headers        (header = 12 bytes)";
    }
}
