package com.bank.enrich;

// Computes per-object and aggregate footprint, with 8-byte alignment.
class FootprintCalculator {
    private final HeaderModel headerModel = new HeaderModel();

    long bytesPerEvent(boolean compact) {
        long raw = headerModel.headerBytes(compact) + SwipeEvent.payloadBytes();
        return ((raw + 7) / 8) * 8; // JVM aligns objects to 8 bytes
    }

    long totalBytes(long eventCount, boolean compact) {
        return eventCount * bytesPerEvent(compact);
    }

    double savingPercent(long eventCount) {
        long traditional = totalBytes(eventCount, false);
        long compact = totalBytes(eventCount, true);
        return 100.0 * (traditional - compact) / traditional;
    }
}
