package com.bank.enrich;

import java.util.logging.*;

public class CompactHeaderDemo {
    private static final Logger log = Logger.getLogger(CompactHeaderDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        HeaderModel headerModel = new HeaderModel();
        FootprintCalculator calc = new FootprintCalculator();

        long events = 100_000_000L; // 100 million card swipes in the pipeline

        log.info(() -> headerModel.describe(false));
        log.info(() -> headerModel.describe(true));

        long perTraditional = calc.bytesPerEvent(false);
        long perCompact = calc.bytesPerEvent(true);
        log.fine(() -> "Per event: traditional=" + perTraditional + "B, compact=" + perCompact + "B");

        long totalTraditional = calc.totalBytes(events, false);
        long totalCompact = calc.totalBytes(events, true);

        log.info(() -> "Traditional heap for " + events + " events: "
                + (totalTraditional / (1024 * 1024)) + " MB");
        log.info(() -> "Compact heap for " + events + " events:     "
                + (totalCompact / (1024 * 1024)) + " MB");

        double pct = calc.savingPercent(events);
        log.info(() -> String.format("Heap AND per-GC copy saving: %.1f%%", pct));

        if (pct >= 20.0) {
            log.warning(() -> "Large saving because events are TINY — header dominated the object.");
        }

        // Create one real event so the demo actually uses the class.
        SwipeEvent e = new SwipeEvent("4111".hashCode(), 245050);
        log.info(() -> "Sample swipe amount (paise): " + e.getAmountPaise());
    }
}

